    override func viewDidLoad() {
        super.viewDidLoad()
        view.backgroundColor =.white
        title = "Localized News Update"
        navigationItem.backButtonTitle = "Back"
        navigationItem.leftBarButtonItem = UIBarButtonItem(title: "Back", style:.plain, target: self, action: #selector(backButtonTapped))
        navigationItem.rightBarButtonItem = UIBarButtonItem(title: "Next", style:.plain, target: self, action: #selector(nextButtonTapped))
        navigationItem.rightBarButtonItem?.isEnabled = false

        // Set up the news update view
        let newsUpdateView = NewsUpdateView()
        newsUpdateView.newsItems = newsItems
        newsUpdateView.demographics = demographics
        newsUpdateView.delegate = self

        // Add the news update view to the view controller
        view.addSubview(newsUpdateView)
        newsUpdateView.translatesAutoresizingMaskIntoConstraints = false
        NSLayoutConstraint.activate([
            newsUpdateView.topAnchor.constraint(equalTo: view.topAnchor, constant: 20),
            newsUpdateView.bottomAnchor.constraint(equalTo: view.bottomAnchor, constant: -20),
            newsUpdateView.leadingAnchor.constraint(equalTo: view.leadingAnchor, constant: 20),
            newsUpdateView.trailingAnchor.constraint(equalTo: view.trailingAnchor, constant: -20)
